template:
% ==========================================================
% 正四棱台 ABCD-A_1B_1C_1D_1
% ==========================================================
% 参数由系统自动注入：
% bottom    下底面边长
% top       上底面边长
% height    棱台高
% showverts 是否显示顶点标签
% showcenter 是否显示 O、O_1 和 OO_1
% showaux   是否显示底面对角线
% showpoints 是否显示额外辅助点
% showhidden 是否显示被遮挡棱的虚线
% ==========================================================

\pgfmathsetmacro{\b}{\bottom}
\pgfmathsetmacro{\t}{\top}
\pgfmathsetmacro{\h}{\height}

% ==========================================================
% 一、定义上下底面中心
% ==========================================================

% 下底面中心 O
\pgfmathsetmacro{\Ox}{0}
\pgfmathsetmacro{\Oy}{0}

% 上底面中心 O_1
% O_1 位于 O 的正上方
\pgfmathsetmacro{\OoneX}{\Ox}
\pgfmathsetmacro{\OoneY}{\Oy + \h}

% ==========================================================
% 二、下底面 ABCD
% ==========================================================
% 以 O 为中心生成下底面
% u、v 表示正方形两组相邻边在二维透视图中的方向
%
% A = O - u - v
% B = O + u - v
% C = O + u + v
% D = O - u + v
%
% 因此：
% O = (A+B+C+D)/4
% ==========================================================

\pgfmathsetmacro{\uxb}{0.50 * \b}
\pgfmathsetmacro{\uyb}{0}

\pgfmathsetmacro{\vxb}{0.38 * \b}
\pgfmathsetmacro{\vyb}{0.48 * \b}

% A
\pgfmathsetmacro{\Ax}{\Ox - \uxb - \vxb}
\pgfmathsetmacro{\Ay}{\Oy - \uyb - \vyb}

% B
\pgfmathsetmacro{\Bx}{\Ox + \uxb - \vxb}
\pgfmathsetmacro{\By}{\Oy + \uyb - \vyb}

% C
\pgfmathsetmacro{\Cx}{\Ox + \uxb + \vxb}
\pgfmathsetmacro{\Cy}{\Oy + \uyb + \vyb}

% D
\pgfmathsetmacro{\Dx}{\Ox - \uxb + \vxb}
\pgfmathsetmacro{\Dy}{\Oy - \uyb + \vyb}

% ==========================================================
% 三、上底面 A_1B_1C_1D_1
% ==========================================================
% 以上底面中心 O_1 为中心生成上底面
% 上底面与下底面采用相同的透视方向
%
% A_1 = O_1 - u_1 - v_1
% B_1 = O_1 + u_1 - v_1
% C_1 = O_1 + u_1 + v_1
% D_1 = O_1 - u_1 + v_1
%
% 因此：
% O_1 = (A_1+B_1+C_1+D_1)/4
% ==========================================================

\pgfmathsetmacro{\uxt}{0.50 * \t}
\pgfmathsetmacro{\uyt}{0}

\pgfmathsetmacro{\vxt}{0.38 * \t}
\pgfmathsetmacro{\vyt}{0.48 * \t}

% A_1
\pgfmathsetmacro{\AoneX}{\OoneX - \uxt - \vxt}
\pgfmathsetmacro{\AoneY}{\OoneY - \uyt - \vyt}

% B_1
\pgfmathsetmacro{\BoneX}{\OoneX + \uxt - \vxt}
\pgfmathsetmacro{\BoneY}{\OoneY + \uyt - \vyt}

% C_1
\pgfmathsetmacro{\ConeX}{\OoneX + \uxt + \vxt}
\pgfmathsetmacro{\ConeY}{\OoneY + \uyt + \vyt}

% D_1
\pgfmathsetmacro{\DoneX}{\OoneX - \uxt + \vxt}
\pgfmathsetmacro{\DoneY}{\OoneY - \uyt + \vyt}

% ==========================================================
% 四、计算图形边界
% ==========================================================

\pgfmathsetmacro{\xmin}{min(\Ax,\Bx,\Cx,\Dx,\AoneX,\BoneX,\ConeX,\DoneX)}
\pgfmathsetmacro{\xmax}{max(\Ax,\Bx,\Cx,\Dx,\AoneX,\BoneX,\ConeX,\DoneX)}
\pgfmathsetmacro{\ymin}{min(\Ay,\By,\Cy,\Dy,\AoneY,\BoneY,\ConeY,\DoneY)}
\pgfmathsetmacro{\ymax}{max(\Ay,\By,\Cy,\Dy,\AoneY,\BoneY,\ConeY,\DoneY)}

% ==========================================================
% 五、自动缩放
% ==========================================================

\pgfmathsetmacro{\figwidth}{\xmax - \xmin}
\pgfmathsetmacro{\figheight}{\ymax - \ymin}
\pgfmathsetmacro{\figsize}{max(\figwidth,\figheight)}
\pgfmathsetmacro{\figscale}{6 / \figsize}

% ==========================================================
% 六、开始绘制
% ==========================================================

\begin{tikzpicture}[
    scale=\figscale,
    every node/.style={
        font=\small,
        fill=none,
        inner sep=1.5pt
    }
]

% ==========================================================
% 七、定义八个顶点
% ==========================================================

\coordinate (A)  at (\Ax,\Ay);
\coordinate (B)  at (\Bx,\By);
\coordinate (C)  at (\Cx,\Cy);
\coordinate (D)  at (\Dx,\Dy);

\coordinate (A1) at (\AoneX,\AoneY);
\coordinate (B1) at (\BoneX,\BoneY);
\coordinate (C1) at (\ConeX,\ConeY);
\coordinate (D1) at (\DoneX,\DoneY);

% ==========================================================
% 八、下底面 ABCD
% ==========================================================

% 前方边 AB
\draw[thick] (A) -- (B);

% 右侧边 BC
\draw[thick] (B) -- (C);

% 后方边 CD
\draw[thick] (C) -- (D);

% 左侧后方边 DA
\ifnum\showhidden>0
    \draw[dashed,thick] (D) -- (A);
\else
    \draw[thick] (D) -- (A);
\fi

% ==========================================================
% 九、上底面 A_1B_1C_1D_1
% ==========================================================

% 前方边 A_1B_1
\draw[thick] (A1) -- (B1);

% 右侧边 B_1C_1
\draw[thick] (B1) -- (C1);

% 后方边 C_1D_1
\draw[thick] (C1) -- (D1);

% 左侧边 D_1A_1
\draw[thick] (D1) -- (A1);

% ==========================================================
% 十、四条侧棱
% ==========================================================

% AA_1
\draw[thick] (A) -- (A1);

% BB_1
\draw[thick] (B) -- (B1);

% CC_1
\draw[thick] (C) -- (C1);

% DD_1
\ifnum\showhidden>0
    \draw[dashed,thick] (D) -- (D1);
\else
    \draw[thick] (D) -- (D1);
\fi

% ==========================================================
% 十一、上下底面中心 O、O_1 及棱台高 OO_1
% ==========================================================

\ifnum\showcenter>0

    \coordinate (O) at (\Ox,\Oy);
    \coordinate (O1) at (\OoneX,\OoneY);

    % 棱台高
    \draw[dashed,thick] (O) -- (O1);

    % 中心点
    \fill (O) circle [radius=0.5pt];
    \fill (O1) circle [radius=0.5pt];

    % 中心标签
    \node[below=4pt] at (O) {$O$};
    \node[above=4pt] at (O1) {$O_1$};

\fi

% ==========================================================
% 十二、底面对角线辅助线
% ==========================================================

\ifnum\showaux>0

    % 下底面两条对角线
    \draw[dashed,thick] (A) -- (C);
    \draw[dashed,thick] (B) -- (D);

    % 上底面两条对角线
    \draw[dashed,thick] (A1) -- (C1);
    \draw[dashed,thick] (B1) -- (D1);

\fi

% ==========================================================
% 十三、顶点标签
% ==========================================================

\ifnum\showverts>0

    % 下底面
    \node[below left=3pt] at (A) {$A$};
    \node[below right=3pt] at (B) {$B$};
    \node[right=4pt] at (C) {$C$};
    \node[left=6pt] at (D) {$D$};

    % 上底面
    \node[above left=3pt] at (A1) {$A_1$};
    \node[right=3pt] at (B1) {$B_1$};
    \node[right=4pt] at (C1) {$C_1$};
    \node[left=4pt] at (D1) {$D_1$};

\fi

% ==========================================================
% 十四、额外辅助点
% ==========================================================

\ifnum\showpoints>0
    % 本基础模板不自动创建未定义的辅助点。
    % 具体题目的辅助点由题目专用模板注入。
\fi

\end{tikzpicture}
